/**
 *  One drawer file, as "Apply selected" names it: the same project, scope
 *  and placeholder path as its [`PlannedFile`].
 */
export type FileRef = {
	projectId: string | null,
	scope: FileScope,
	file: string,
};

/**  Which layer a client file belongs to (SPEC 6.1). */
export type FileScope = "user" | "project" | "project_local";

/**  A manifest the folder holds already (Add binds it). */
export type FoundManifest = {
	id: string,
	name: string,
	layout: ManifestLayout,
	/**  This machine knows the project already. */
	known: boolean,
};

/**
 *  A failed command: the stable code the frontend localizes from, plus
 *  English diagnostic detail (never shown as state).
 */
export type IpcError = {
	code: ErrorCode,
	message: string,
};

/**
 *  An environment variable or header: the value is a literal or holds
 *  references (`${secret:ALIAS}`, `${env:NAME}`), never a secret itself.
 */
export type KeyValue = {
	key: string,
	value: string,
};

/**  The layer an entry comes from (SPEC 6.4); the legend's S, P, L, F, C. */
export type LayerKind = "system" | "project" | "project_local" | 
/**  An entry Loadout does not own in one of the client's files. */
"foreign" | 
/**  An entry the client reads from another tool's file. */
"client_compat";

/**  A layer and the file (under its placeholder root) of one entry. */
export type LayerRef = {
	layer: LayerKind,
	file: string,
};

/**  How a manifest file compares with the content last trusted. */
export type ManifestChangeKind = "new" | "changed" | "unchanged" | "removed";

/**  The manifest files of a project folder (SPEC 5.5). */
export type ManifestLayout = 
/**  Only `.loadout/project.local.toml`. */
"private" | 
/**  Only `.loadout/project.toml`. */
"shared" | 
/**  Both files. */
"shared_and_local";

/**
 *  One client's entry of a server name: the matrix cell and its
 *  provenance chain.
 */
export type MatrixCell = {
	client: string,
	/**  The entry the client uses. */
	winner: LayerRef,
	/**  `store:<id>`, `store:<id>+project`, `project:<name>` or `foreign`. */
	source: string,
	/**  The client starts it (not suppressed, disabled or blocked). */
	loaded: boolean,
	shadowed: LayerRef[],
	/**  Other clients that read the winner's file and container. */
	alsoVisibleTo: string[],
	status: EntryStateKind | null,
	warnings: IpcError[],
	/**  The winner's native entry as its file writes it, masked. */
	snippet: string | null,
};

export type MatrixClient = {
	id: string,
	name: string,
	detected: boolean,
};

export type MatrixRow = {
	name: string,
	/**
	 *  One cell per client that loads (or would load) the name; a client
	 *  whose own layers coexist (Cursor) can have several.
	 */
	cells: MatrixCell[],
};

/**  Planned or done create, update, remove and disable operations. */
export type OpCounts = {
	create: number,
	update: number,
	remove: number,
	disable: number,
};

/**  Result of an apply run or of one file (SPEC 8.7). */
export type OutcomeKind = "ok" | "partial" | "blocked" | "failed";

export type PendingPlan = {
	applyMode: ApplyModeKind,
	/**  Files with work, decisions or problems. */
	files: PlannedFile[],
	/**
	 *  Entries waiting for an apply, a decision, or blocked: the header's
	 *  pending-changes pill (SPEC 13.1).
	 */
	pending: number,
	writes: number,
	unresolved: number,
	warnings: IpcError[],
};

/**  A folder picked in the OS dialog, as the frontend sees it. */
export type PickedFolder = {
	/**  Names the folder in `add_project` and `init_project`. */
	token: string,
	/**  The folder under its placeholder root. */
	path: string,
	/**  The folder's own name (the default project name). */
	name: string,
	/**  `None`: no manifest; the page offers Init (Private preselected). */
	manifest: FoundManifest | null,
};

/**  A pill's state (SPEC 13.2). */
export type PillState = 
/**  Not enabled, and nothing of it in the client's file. */
"disabled" | 
/**  Enabled and written as desired. */
"enabled" | 
/**  The store and the client file differ until the next apply. */
"pending" | 
/**
 *  The file changed since it was written, or collides with a foreign
 *  entry: needs a decision.
 */
"drift" | 
/**  Cannot be written; see the reason. */
"blocked" | 
/**  The client has no MCP config at this scope or on this OS. */
"not_supported";

export type PlannedEntry = {
	action: ActionKind,
} & EntryNote;

/**  One client file of the pending plan. */
export type PlannedFile = {
	/**  The file under its placeholder root (`~/...`, `<P>/...`). */
	file: string,
	clients: string[],
	scope: FileScope,
	projectId: string | null,
	/**
	 *  The project folder under its placeholder root, for a project or
	 *  project-local file.
	 */
	project: string | null,
	counts: OpCounts,
	/**
	 *  Unified diff of the file text, with values written `inline` and
	 *  anything else that may be a secret masked; empty when the file
	 *  stays as it is.
	 */
	diff: string,
	/**  Entries that change, need a decision or are blocked. */
	entries: PlannedEntry[],
	/**  The whole file is blocked (`parse_error`, `trust_required`, ...). */
	problem: IpcError | null,
	warnings: IpcError[],
};

/**
 *  Operating system the app runs on; selects the window chrome (SPEC 13.1:
 *  custom controls on Windows, native decorations on Linux, Overlay title
 *  bar on macOS).
 */
export type Platform = "windows" | "linux" | "macos";

/**  What a project change did. */
export type ProjectChange = {
	id: string,
	trust: ProjectTrust,
} & ChangeResult;

/**  One project of the Projects page. */
export type ProjectRow = {
	id: string,
	name: string,
	/**  The folder under its placeholder root (`~/Code/app`). */
	path: string,
	layout: ManifestLayout | null,
	trust: ProjectTrust,
	error: IpcError | null,
	/**  Server names the manifests define. */
	servers: number,
	/**  Clients with an entry of this project. */
	clients: number,
	/**  Entries waiting for an apply, a decision, or blocked. */
	pending: number,
};

/**  Trust of a known project's manifests (SPEC 17). */
export type ProjectTrust = "trusted" | 
/**  Never trusted on this machine. */
"untrusted" | 
/**  Changed since trusted (for example after `git pull`). */
"changed" | 
/**  The folder is gone. */
"missing" | 
/**  No usable manifest (see the row's error). */
"invalid";

/**  A resolver action (SPEC 8.2 default actions, 13.4 buttons). */
export type ResolveAction = 
/**  Write the desired entry over the file's (adopting a collision). */
"overwrite" | 
/**
 *  Turn the file's entry into the store server ("Import their
 *  change", "Import theirs").
 */
"import_theirs" | 
/**
 *  Stop managing the entry: it stays as it is, and the server is no
 *  longer enabled for this client.
 */
"release" | 
/**  Leave it for now. */
"skip" | 
/**  A deleted entry: write it again. */
"recreate" | 
/**  A deleted entry: remove the client from the server's enable list. */
"respect_deletion" | 
/**  A drifted entry no longer desired: remove it anyway. */
"remove_anyway";

/**  What the resolver shows for one entry. */
export type ResolverDetail = {
	/**  The file under its placeholder root. */
	file: string,
	/**  The project folder under its placeholder root, for a project file. */
	project: string | null,
	client: string,
	name: string,
	server: string | null,
	state: EntryStateKind,
	/**
	 *  The entry as Loadout last wrote it; `None` when it was never
	 *  written (a collision) or cannot be recovered.
	 */
	lastWritten: string | null,
	/**  The entry in the file now; `None` when it was deleted. */
	current: string | null,
	/**  The entry the store wants; `None` when it is no longer desired. */
	desired: string | null,
	/**  The actions this state allows, the default first. */
	actions: ResolveAction[],
	problem: IpcError | null,
	/**
	 *  Keyed hash of what is shown (state, file entry, desired entry);
	 *  `resolve_entry` sends it back and is refused (`entry_changed`) when
	 *  the entry changed in between.
	 */
	fingerprint: string,
};

/**  One manifest file of the trust review. */
export type ReviewedFile = {
	/**  `project.toml` or `project.local.toml`. */
	file: string,
	/**  `<P>/.loadout/<file>`. */
	path: string,
	change: ManifestChangeKind,
	/**  The file now (masked); for a new file the whole review. */
	content: string | null,
	/**  Unified diff from the trusted content (masked), for a changed file. */
	diff: string | null,
};

/**
 *  A configuration scope the sidebar switcher offers (SPEC 13.1). Projects
 *  join in M16.
 */
export type Scope = 
/**  User-wide configuration of every client. */
{ kind: "system" };

export type ServerDetail = {
	/**
	 *  The Form view; `None` when the file does not load (see `invalid`),
	 *  so only the TOML tab can fix it.
	 */
	draft: ServerDraft | null,
	invalid: IpcError | null,
	/**  `store/servers/<id>.toml` as it is. */
	toml: string,
};

/**
 *  The edit dialog's Form (SPEC 13.2). Store values only: the store never
 *  holds a secret value (SPEC 11.8), so nothing here needs masking.
 */
export type ServerDraft = {
	id: string,
	displayName: string | null,
	description: string | null,
	transport: TransportKind,
	command: string | null,
	args: string[],
	url: string | null,
	cwd: string | null,
	env: KeyValue[],
	headers: KeyValue[],
	clients: ClientChoice,
	delivery: DeliveryKind | null,
	toolsAllow: string[],
	toolsDeny: string[],
};

export type ServerList = {
	servers: ServerRow[],
	/**  Clients with an MCP config, in adapter table order. */
	clients: ClientInfo[],
	/**  Plan problems outside any server row. */
	warnings: IpcError[],
};

/**  One row of the MCP page. */
export type ServerRow = {
	id: string,
	displayName: string | null,
	description: string | null,
	transport: TransportKind | null,
	/**
	 *  Command and arguments, or the URL, as stored: references are shown,
	 *  values never.
	 */
	launch: string,
	origin: string | null,
	tags: string[],
	clients: ClientChoice,
	/**  One pill per client the page lists, in [`ServerList::clients`] order. */
	pills: ClientPill[],
	/**  Problems of this server's entries (`missing_secret`, ...), once each. */
	problems: IpcError[],
	/**
	 *  The server file does not load; the row offers only Edit (TOML) and
	 *  Delete.
	 */
	invalid: IpcError | null,
};

export type TierKind = "a" | "b" | "c" | "d";

export type ToolFile = {
	path: string,
	exists: boolean,
};

/**  One client on the Tools page. */
export type ToolInfo = {
	id: string,
	name: string,
	tier: TierKind,
	detected: boolean,
	/**  Has an MCP config on this operating system. */
	supported: boolean,
	/**  Loadout only reads this client (`vscode-legacy`). */
	readOnly: boolean,
	/**  User-scope MCP files (the first existing one is used). */
	userFiles: ToolFile[],
	/**
	 *  Project files, relative to the project folder (`<P>/...`) or absolute
	 *  for a user file keyed by project.
	 */
	projectFiles: string[],
	transports: Transports,
	/**  The client expands environment references (`${env:NAME}`) itself. */
	envRefs: boolean,
	/**  The client reads its file only at launch. */
	restartRequired: boolean,
	warnings: IpcError[],
};

export type TransportKind = "stdio" | "http" | "sse";

export type Transports = {
	stdio: boolean,
	http: boolean,
	sse: boolean,
};

/**  The trust review of a project: what trusting it would accept. */
export type TrustReview = {
	id: string,
	name: string,
	path: string,
	trust: ProjectTrust,
	/**
	 *  The manifests' content hash; `trust_project` trusts only this
	 *  content.
	 */
	hash: string,
	files: ReviewedFile[],
	/**  Manifest validation warnings. */
	warnings: IpcError[],
};

export type UndoResult = {
	applyId: string,
	/**  Store files restored from before the run. */
	restored: string[],
	/**  The `auto/pre-rollback/<ts>` tag. */
	tag: string,
	commit: string | null,
	apply: ApplyRun,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}
